//! This module provides a public function [`version()`] that returns the object of [`semver::Version`].
//!
//! The version string is automatically retrieved via `env!("CARGO_PKG_VERSION")`, assuming it yields a non-empty,
//! valid version string conforming to the Semantic Versioning specification.
use semver::Error;
#[doc(inline)]
pub use semver::Version;

/// Returns the version information of the library.
///
/// The library version is declared in `Cargo.toml` and this function parses the declared value using [`semver`] crate.
///
/// # Return
/// This function returns [`semver::Version`] object.
pub fn version() -> Version {
    parse_version(fetch_package_version()).unwrap()
}

fn fetch_package_version() -> &'static str {
    // get version string from environment variable
    env!("CARGO_PKG_VERSION")
}

fn parse_version(text: &str) -> Result<Version, Error> {
    Version::parse(text)
}

#[cfg(test)]
mod test {
    use claim::assert_ok;

    use super::*;

    #[test]
    fn version_is_declared() {
        // [Requirement]
        // Version declaration should not be blank.
        let version_str = fetch_package_version();
        assert!(!version_str.is_empty());
    }

    #[test]
    fn version_is_semantically_valid() {
        // [Assumption]
        // Version declaration is valid if it is parsable.
        let version = parse_version(fetch_package_version());
        assert_ok!(version);
    }
}

