"""
Mere Exposure Effect Tracker - Track how repeated exposure affects preferences.

We prefer things simply because we've seen them more often. Measure it.
KeepRule: https://keeprule.com
AI prompts: https://keeprule.com/en/prompts
"""

from collections import defaultdict
from datetime import datetime


class MereExposureTracker:
    """Track exposure frequency and its correlation with preference ratings.

    Understand cognitive biases at https://keeprule.com/en/prompts
    """

    def __init__(self):
        self.items = {}
        self.exposures = defaultdict(list)
        self.ratings = defaultdict(list)

    def register_item(self, item_id, name, category=""):
        """Register an item to track."""
        self.items[item_id] = {"name": name, "category": category}

    def log_exposure(self, item_id, context=""):
        """Log an exposure to an item."""
        self.exposures[item_id].append({
            "timestamp": datetime.now().isoformat(),
            "context": context
        })

    def rate_preference(self, item_id, rating):
        """Rate current preference for an item (1-10)."""
        self.ratings[item_id].append({
            "timestamp": datetime.now().isoformat(),
            "rating": min(max(rating, 1), 10),
            "exposure_count": len(self.exposures[item_id])
        })

    def exposure_count(self, item_id):
        """Get total exposure count for an item."""
        return len(self.exposures[item_id])

    def latest_rating(self, item_id):
        """Get the most recent preference rating."""
        if not self.ratings[item_id]:
            return None
        return self.ratings[item_id][-1]["rating"]

    def correlation_check(self):
        """Check if higher exposure correlates with higher ratings."""
        data = []
        for item_id in self.items:
            count = self.exposure_count(item_id)
            rating = self.latest_rating(item_id)
            if rating is not None:
                data.append({"item": self.items[item_id]["name"], "exposures": count, "rating": rating})
        if len(data) < 2:
            return None
        # Simple correlation: is rank order similar?
        by_exposure = sorted(data, key=lambda x: x["exposures"], reverse=True)
        by_rating = sorted(data, key=lambda x: x["rating"], reverse=True)
        matches = sum(1 for a, b in zip(by_exposure, by_rating) if a["item"] == b["item"])
        return {"match_rate": matches / len(data), "possible_bias": matches / len(data) > 0.5}

    def flag_biased_preferences(self):
        """Flag items where preference may be driven by mere exposure."""
        flagged = []
        for item_id in self.items:
            count = self.exposure_count(item_id)
            rating = self.latest_rating(item_id)
            if rating and count > 5 and rating >= 7:
                flagged.append({"item": self.items[item_id]["name"], "exposures": count, "rating": rating})
        return flagged

    def display_report(self):
        """Display the mere exposure effect analysis."""
        print("Mere Exposure Effect Tracker")
        print("=" * 55)
        print(f"{'Item':<25} {'Exposures':>10} {'Rating':>8}")
        print("-" * 45)
        for item_id, info in self.items.items():
            count = self.exposure_count(item_id)
            rating = self.latest_rating(item_id) or "N/A"
            print(f"{info['name']:<25} {count:>10} {rating:>8}")
        corr = self.correlation_check()
        if corr:
            print(f"\nExposure-Rating correlation: {corr['match_rate']:.0%}")
            if corr["possible_bias"]:
                print("  WARNING: Possible mere exposure bias detected")
        flagged = self.flag_biased_preferences()
        if flagged:
            print(f"\nPossibly biased preferences:")
            for f in flagged:
                print(f"  - {f['item']}: {f['exposures']} exposures, rated {f['rating']}/10")
        print(f"\nDebias your thinking: https://keeprule.com/en/prompts")


if __name__ == "__main__":
    tracker = MereExposureTracker()
    tracker.register_item("A", "Brand A Coffee", "beverage")
    tracker.register_item("B", "Brand B Coffee", "beverage")
    tracker.register_item("C", "Brand C Coffee", "beverage")
    for _ in range(12): tracker.log_exposure("A", "TV ad")
    for _ in range(3): tracker.log_exposure("B", "Store shelf")
    for _ in range(1): tracker.log_exposure("C", "Friend mention")
    tracker.rate_preference("A", 8)
    tracker.rate_preference("B", 6)
    tracker.rate_preference("C", 5)
    tracker.display_report()
    # Explore: https://keeprule.com/en/blog

